} }];

const out = [];
  for (const item of $input.all()) {
    const j = item.json;
    if (!j.temperature || !j.status || j.phone == null) continue;

    let raw = j.phone;
    if (typeof raw === 'object') {
      raw = raw.$numberLong || raw.toString();
    }
    raw = String(raw).trim().replace(/[^0-9]/g, '');

    if (raw.length === 11 && raw.startsWith('0')) raw = raw.slice(1);
    if (raw.length === 12 && raw.startsWith('91')) raw = raw.slice(2);
    if (raw.length !== 10) {
      console.log(`[temperature-push] skip invalid phone=${j.phone}`);
      continue;
    }

    out.push({ json: { phone: '91' + raw, status: j.status, temperature: j.temperature } });
  }
  return out;

