// Patch reportData.sessions_detail with appt_status from the appointments query.
// Mirrors the enrichment block in scripts/run_local_report.py.
const reportData = $input.first().json;
function normPhone(p) {
  if (p == null) return null;
  let s = String(p).trim().replace(/^\+/, '');
  if (s.length === 12 && s.startsWith('91')) s = s.slice(2);
  return s;
}
// Walk the merged stream to find the appointment lookup docs.
const apptByPhone = {};
for (const it of $('Flatten to Tagged Items').all()) {
  const j = (it && it.json) || {};
  if (j._queryType !== 'appointments_today') continue;
  const ph = normPhone(j._id || j.phone);
  if (ph) apptByPhone[ph] = j;
}
let enriched = 0;
for (const row of (reportData.sessions_detail || [])) {
  const a = apptByPhone[normPhone(row.phone)];
  if (a && a.appt_status) {
    row.appt_status   = a.appt_status;
    row.cancel_reason = a.cancel_reason || null;
    enriched++;
  }
}
console.log(`[enrich] populated appt_status on ${enriched}/${(reportData.sessions_detail || []).length} session rows`);
// Pass pairedItem through so downstream Generate HTML / HTML to Binary can
// trace lineage back to Calculate Windows without n8n complaining.
return [{ json: reportData, pairedItem: { item: 0 } }];

const html = $input.item.json.html;
const buffer = Buffer.from(html, 'utf8');
const binaryData = await this.helpers.prepareBinaryData(buffer, 'index.html', 'text/html');
return [{ json: $input.item.json, binary: { data: binaryData } }];

