parameters.jsCode:
// Convert mixed input stream into the {_queryType: ...} item shape that
// Build Report Data expects. Inputs (in merge order):
//   index 0: Facet doc (single doc with 14 array fields)
//   index 1: Query WTD doc
//   index 2: Query Prev Week doc
//   index 3..N: Query Appointments Today docs
//
// Every output item carries `pairedItem: { item: 0 }` so n8n can trace
// $('Calculate Windows1').item.json all the way through downstream nodes
// (Build Report Data + Enrich Appt Status both call that).
const FACET_BUCKETS = ["new_leads", "older_leads", "older_stage", "status_counts", "plat_stats", "sessions", "temperature", "wtd_new_leads_count", "prev_new_leads_count", "wtd_bookings_count", "prev_bookings_count", "fv_bookings", "status_changed_today", "scheduled_transitions"];
const items = [];
let standaloneSeen = 0;  // tracks order: 0=wtd, 1=prev_week
for (const it of $input.all()) {
  const j = (it && it.json) || {};
  // Facet result has all 14 bucket keys as arrays
  const isFacet = FACET_BUCKETS.every(k => Array.isArray(j[k]));
  if (isFacet) {
    for (const b of FACET_BUCKETS) {
      for (const d of j[b]) {
        items.push({ json: { ...d, _queryType: b }, pairedItem: { item: 0 } });
      }
    }
    continue;
  }
  // Appointments docs have appt_status / cancel_reason
  if ('appt_status' in j || 'cancel_reason' in j) {
    items.push({ json: { ...j, _queryType: 'appointments_today' }, pairedItem: { item: 0 } });
    continue;
  }
  // The remaining standalones — WTD then Prev Week, in merge order
  const qtype = standaloneSeen === 0 ? 'wtd' : 'prev_week_sessions';
  standaloneSeen++;
  items.push({ json: { ...j, _queryType: qtype }, pairedItem: { item: 0 } });
}
return items;

// Pluck out the items that drive temperature recalculation.
// Mirrors the original Merge Temp Candidates which combined
//   Query Status Changed Today + Query Scheduled Transitions.
const out = [];
for (const it of $input.all()) {
  const j = (it && it.json) || {};
  if (j._queryType === 'status_changed_today' || j._queryType === 'scheduled_transitions') {
    out.push({ json: j, pairedItem: { item: 0 } });
  }
}
return out;
